"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["47465"],{99199(e){e.exports=JSON.parse('{"id":"F129","slug":"dupont-analysis","name":"DuPont Analysis (3-Step and 5-Step)","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"DuPont analysis","level":"Intermediate","aliases":["DuPont identity","ROE decomposition","tax burden","interest burden"],"formula":{"latex":"ROE=\\\\frac{NI}{S}\\\\times\\\\frac{S}{TA}\\\\times\\\\frac{TA}{E}=\\\\frac{NI}{EBT}\\\\times\\\\frac{EBT}{EBIT}\\\\times\\\\frac{EBIT}{S}\\\\times\\\\frac{S}{TA}\\\\times\\\\frac{TA}{E}","also":[],"text":"ROE = Net margin x Asset turnover x Equity multiplier. Five-step: ROE = Tax burden x Interest burden x EBIT margin x Asset turnover x Equity multiplier"},"symbols":[{"symbol":"NI/S","meaning":"Net profit margin","unit":"percent"},{"symbol":"S/TA","meaning":"Asset turnover, sales per unit of assets","unit":"times"},{"symbol":"TA/E","meaning":"Equity multiplier, assets per unit of equity (leverage)","unit":"times"},{"symbol":"NI/EBT","meaning":"Tax burden, the share of pre-tax profit kept after tax","unit":"percent"},{"symbol":"EBT/EBIT","meaning":"Interest burden, the share of operating profit left after interest","unit":"percent"}],"when_to_use":"Use it to find out why ROE is high or low. It splits ROE into profitability, efficiency and leverage. Two companies with the same ROE can be very different: one a high-margin business and the other a thin-margin business using lots of debt.","worked_example":{"problem":"A company has net income of 90, pre-tax profit of 120, EBIT of 160, sales of 1,500, average assets of 1,200 and average equity of 500.","inputs":{"ni":90,"ebt":120,"ebit":160,"s":1500,"ta":1200,"e":500},"steps":[{"label":"Net margin = NI / sales","working":"90 / 1500","value":"6.00%"},{"label":"Asset turnover = sales / assets","working":"1500 / 1200","value":"1.25"},{"label":"Equity multiplier = assets / equity","working":"1200 / 500","value":"2.40"},{"label":"ROE = net margin x turnover x multiplier","working":"0.06 x 1.25 x 2.4","value":"18.00%"},{"label":"Tax burden = NI / EBT","working":"90 / 120","value":"75.00%"},{"label":"Interest burden = EBT / EBIT","working":"120 / 160","value":"75.00%"},{"label":"EBIT margin = EBIT / sales","working":"160 / 1500","value":"10.67%"},{"label":"ROE from five steps","working":"0.75 x 0.75 x 0.106667 x 1.25 x 2.4","value":"18.00%"}],"answer":"ROE is 18.00%. Net margin is 6.00%, asset turnover is 1.25 and the equity multiplier is 2.40. In the five-step version the tax burden is 75.00%, the interest burden 75.00% and the EBIT margin 10.67%. Their product also gives 18.00%. Leverage is doing a lot of the work: the company earns 6 cents on each unit of sales."},"calculator":{"available":true,"inputs":[{"id":"ni","label":"Net income","unit":"money","type":"number","default":90,"hint":""},{"id":"ebt","label":"Pre-tax profit","unit":"money","type":"number","default":120,"hint":""},{"id":"ebit","label":"EBIT","unit":"money","type":"number","default":160,"hint":""},{"id":"s","label":"Sales","unit":"money","type":"number","default":1500,"hint":""},{"id":"ta","label":"Average total assets","unit":"money","type":"number","default":1200,"hint":""},{"id":"e","label":"Average equity","unit":"money","type":"number","default":500,"hint":""}],"checks":[{"expr":"s>0 and ta>0 and e>0 and ebt>0 and ebit>0","message":"Sales, assets, equity and the profit figures must be above zero."}],"steps":[{"id":"nm","label":"Net margin = NI / sales","expr":"ni/s","format":"pct2"},{"id":"at","label":"Asset turnover = sales / assets","expr":"s/ta","format":"num2"},{"id":"em","label":"Equity multiplier = assets / equity","expr":"ta/e","format":"num2"},{"id":"roe","label":"ROE = net margin x turnover x multiplier","expr":"nm*at*em","format":"pct2"},{"id":"tb","label":"Tax burden = NI / EBT","expr":"ni/ebt","format":"pct2"},{"id":"ib","label":"Interest burden = EBT / EBIT","expr":"ebt/ebit","format":"pct2"},{"id":"ebm","label":"EBIT margin = EBIT / sales","expr":"ebit/s","format":"pct2"},{"id":"roe5","label":"ROE from five steps","expr":"tb*ib*ebm*at*em","format":"pct2"}],"results":["roe","nm","at","em"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"nm":0.06,"at":1.25,"em":2.4,"roe":0.18,"tb":0.75,"ib":0.75,"ebm":0.10666666666666667,"roe5":0.18}},"finder":{"finds":"What drives ROE: margin, efficiency or leverage","needs":"Net income, EBT, EBIT, sales, average assets and equity"},"related":[{"slug":"return-on-equity","name":"Return on Equity (ROE)"},{"slug":"return-on-assets","name":"Return on Assets (ROA)"},{"slug":"equity-multiplier","name":"Equity Multiplier"},{"slug":"profit-margins","name":"Profit Margins"}],"related_ids":["F128","F127","F008","F066"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>R</mi><mi>O</mi><mi>E</mi><mo>=</mo><mfrac><mrow><mi>N</mi><mi>I</mi></mrow><mi>S</mi></mfrac><mo>\xd7</mo><mfrac><mi>S</mi><mrow><mi>T</mi><mi>A</mi></mrow></mfrac><mo>\xd7</mo><mfrac><mrow><mi>T</mi><mi>A</mi></mrow><mi>E</mi></mfrac><mo>=</mo><mfrac><mrow><mi>N</mi><mi>I</mi></mrow><mrow><mi>E</mi><mi>B</mi><mi>T</mi></mrow></mfrac><mo>\xd7</mo><mfrac><mrow><mi>E</mi><mi>B</mi><mi>T</mi></mrow><mrow><mi>E</mi><mi>B</mi><mi>I</mi><mi>T</mi></mrow></mfrac><mo>\xd7</mo><mfrac><mrow><mi>E</mi><mi>B</mi><mi>I</mi><mi>T</mi></mrow><mi>S</mi></mfrac><mo>\xd7</mo><mfrac><mi>S</mi><mrow><mi>T</mi><mi>A</mi></mrow></mfrac><mo>\xd7</mo><mfrac><mrow><mi>T</mi><mi>A</mi></mrow><mi>E</mi></mfrac></mrow><annotation encoding=\\"application/x-tex\\">ROE=\\\\frac{NI}{S}\\\\times\\\\frac{S}{TA}\\\\times\\\\frac{TA}{E}=\\\\frac{NI}{EBT}\\\\times\\\\frac{EBT}{EBIT}\\\\times\\\\frac{EBIT}{S}\\\\times\\\\frac{S}{TA}\\\\times\\\\frac{TA}{E}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"dual-class-voting-power","name":"Dual-Class Shares: Voting Power vs. Ownership"},"next":{"slug":"duration-gap","name":"Duration Gap and Equity Sensitivity"},"lesson":null,"total":522}')}}]);